{
  "findings": [
    {
      "title": "Blood volume table arithmetic error: sum of components does not equal total",
      "page": 97,
      "quote": "35 mL + 260 mL + 375 mL + 45 mL + 10 mL = 725 mL",
      "severity": "major"
    },
    {
      "title": "CT slice thickness inconsistency in RECIST measurability criteria",
      "page": 99,
      "quote": "1 cm by CT scan (CT scan slice thickness no greater than 0.5 cm)",
      "severity": "major"
    },
    {
      "title": "Pathological lymph node size range is internally contradictory",
      "page": 99,
      "quote": "pathological lymph nodes with ≥ 10 to < 1.5 cm short axis",
      "severity": "major"
    },
    {
      "title": "Target lesion selection example contradicts maximum of 2 per organ",
      "page": 100,
      "quote": "in instances where subjects have only 1 or 2 organ sites involved a maximum of 2 and 4 lesions, respectively, will be recorded",
      "severity": "major"
    },
    {
      "title": "RECIST PD absolute increase threshold incorrect (should be 5 mm, not 0.5 cm)",
      "page": 100,
      "quote": "the sum must also demonstrate an absolute increase of at least 0.5 cm",
      "severity": "major"
    },
    {
      "title": "iRECIST formula for percent change is malformed and ambiguous",
      "page": 105,
      "quote": "Change in (%) = ([∑Follow-up - ∑Baseline/ ∑Nadir]/ ∑Baseline/ ∑Nadir) * 100",
      "severity": "major"
    },
    {
      "title": "iRECIST iUPD criteria missing absolute increase requirement",
      "page": 106,
      "quote": "increase in the sum of all target lesions by at least 20% (but at least ≥ 5 mm)",
      "severity": "major"
    },
    {
      "title": "iRECIST statement about decrease after iUPD is ambiguous and potentially contradictory",
      "page": 107,
      "quote": "if the tumor burden decreases more than 20%, this should be considered iSD; if it decreases more than 30%, this should be considered iPR",
      "severity": "minor"
    },
    {
      "title": "itRECIST reference citation has inconsistent author initials",
      "page": 108,
      "quote": "Goldmacher GV, Khilnani AD, Andtbacka R, Luke RJ, F. Hodi S, et al.",
      "severity": "minor"
    }
  ]
}
